use vstd::prelude::*;

verus! {

fn copy(arr: &Vec<i8>) -> (result: Vec<i8>)
    ensures
        // Functional correctness: result is element-wise equal to `arr`.
        result@ == arr@,
        // Length is preserved.
        result@.len() == arr@.len(),
{
    let mut result: Vec<i8> = Vec::with_capacity(arr.len());

    for &x in arr.iter()
        invariant
            // The output is never longer than the input.
            result@.len() <= arr@.len(),
            // `result` equals the prefix of `arr` built so far.
            result@ == arr@.subrange(0, result@.len() as int),
    {
        result.push(x);
    }

    result
}

} // verus!